import type { AnswerValue } from './types';
import { AI_SENT_QUESTION_IDS } from './aiDraft';

const D = '[0-9０-９]';
const SEP = '[-‐‑–—−－ー ]';
const URL_RE = /(?:https?:\/\/|www\.)[^\s<>"'「」（）()、。]+/giu;
const EMAIL_RE = /[A-Za-z0-9._%+-]+[@＠][A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+/gu;
const POSTAL_RE = new RegExp(`〒 ?${D}{3}${SEP}?${D}{4}|(?<![-0-9０-９－ー])${D}{3}[-－ー]${D}{4}(?![-0-9０-９－ー])`, 'gu');
const PHONE_RE = new RegExp(`(?<![0-9０-９])(?:[+＋] ?(?:81|８１)${SEP}?[(（]?0?[)）]?|0|０)${D}(?:${SEP}?[()（）]?${D}){7,11}(?![0-9０-９])`, 'gu');

const digitsOf = (s: string) => s.replace(/[０-９]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0xfee0)).replace(/\D/g, '');

function isPhone(m: string): boolean {
  const d = digitsOf(m);
  if (/^[+＋]/.test(m)) return d.length >= 11 && d.length <= 13; // 81 + 9〜10 桁（先頭の 0 を書く表記も許す）
  return d.length >= 10 && d.length <= 11 && d.startsWith('0');
}

/** メール → [メール]・電話 → [電話]・URL → [URL]・郵便番号 → [郵便番号]（URL を先に消す: URL 内のメール風の文字列ごと消す） */
export function redactText(s: string): string {
  return s
    .replace(URL_RE, '[URL]')
    .replace(EMAIL_RE, '[メール]')
    .replace(POSTAL_RE, '[郵便番号]')
    .replace(PHONE_RE, (m) => (isPhone(m) ? '[電話]' : m));
}

/** URL（スキームなしも可）→ ホスト名（小文字・先頭の www. を除く）。解釈できなければ '' */
export function hostnameOf(raw: string): string {
  const s = raw.trim();
  if (!s) return '';
  try {
    const u = new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(s) ? s : `https://${s}`);
    if (u.protocol !== 'http:' && u.protocol !== 'https:') return '';
    return u.hostname.toLowerCase().replace(/^www\./, '');
  } catch {
    return '';
  }
}

const asText = (v: AnswerValue | undefined): string => (Array.isArray(v) ? v.join('\n') : v ?? '');

/** q-competitor の回答（空白・改行・読点区切りの URL）→ ホスト名（重複なし・最大 5） */
export function competitorHostsOf(answers: Record<string, AnswerValue>): string[] {
  const hosts = asText(answers['q-competitor']).split(/[\s、,，]+/u).map(hostnameOf).filter(Boolean);
  return [...new Set(hosts)].slice(0, 5);
}

export type SentAnswers = Record<string, string | string[]>;

/**
 * AI へ送る回答（設計 §4）。AI_SENT_QUESTION_IDS だけ（q-infra・q-dns-* は送らない）。
 * q-url はホスト名だけ、q-competitor は回答には入れない（competitorHostsOf で別に渡す）。自由記述は redactText を通す。空の回答は省く
 */
export function buildSentAnswers(answers: Record<string, AnswerValue>): SentAnswers {
  const out: SentAnswers = {};
  for (const id of AI_SENT_QUESTION_IDS) {
    const v = answers[id];
    if (id === 'q-competitor') continue;
    if (id === 'q-url') {
      const h = hostnameOf(asText(v));
      if (h) out[id] = h;
      continue;
    }
    if (Array.isArray(v)) {
      const list = v.map((x) => redactText(String(x)).trim()).filter(Boolean);
      if (list.length) out[id] = list;
    } else if (typeof v === 'string' && v.trim()) {
      out[id] = redactText(v).trim();
    }
  }
  return out;
}

/** 生成の前に必ず答える質問（validation.ts の REQUIRED_FOR_ANALYSIS と同じ 4 問。設計 §1） */
export const AI_REQUIRED_QUESTION_IDS = ['q-url', 'q-purpose', 'q-issue', 'q-improve'] as const;

/** validation.ts の isAnswered と同じ判定 */
export function isAnsweredValue(v: unknown): boolean {
  return Array.isArray(v) ? v.length > 0 : typeof v === 'string' && v.trim().length > 0;
}

/** 欠けている必須の質問 ID */
export function missingRequired(answers: Record<string, unknown>): string[] {
  return AI_REQUIRED_QUESTION_IDS.filter((id) => !isAnsweredValue(answers[id]));
}
